1	using System.Globalization;
2	using System.Text;
3	using System.Text.RegularExpressions;
4	
5	namespace BatchRenameStudio.Core;
6	
7	/// <summary>
8	/// The 14 op implementations and the step dispatcher.
9	/// Every op is a safety-netted no-op on any unexpected exception (SPEC §6):
10	/// each Apply* method computes its result locally and only assigns it to
11	/// ctx.Target/ctx.CurrentExtension once fully computed, so a thrown exception
12	/// never leaves a partially-mutated target.
13	/// </summary>
14	public static class Operations
15	{
16	    private static readonly TimeSpan RegexTimeout = TimeSpan.FromSeconds(1);
17	
18	    public static void Apply(StepSpec step, OpContext ctx)
19	    {
20	        try
21	        {
22	            switch (step.Op)
23	            {
24	                case "replace": Replace(step, ctx); break;
25	                case "insert": Insert(step, ctx); break;
26	                case "remove": Remove(step, ctx); break;
27	                case "sequence": Sequence(step, ctx); break;
28	                case "case": CaseOp(step, ctx); break;
29	                case "extension": Extension(step, ctx); break;
30	                case "pad": Pad(step, ctx); break;
31	                case "trim": Trim(step, ctx); break;
32	                case "slug": Slug(step, ctx); break;
33	                case "translate": Translate(step, ctx); break;
34	                case "numberFormat": NumberFormat(step, ctx); break;
35	                case "extract": Extract(step, ctx); break;
36	                case "template": Template(step, ctx); break;
37	                case "dedupeChars": DedupeChars(step, ctx); break;
38	                default:
39	                    // Unknown op: treated as a no-op, still recorded in the trace by the caller.
40	                    break;
41	            }
42	        }
43	        catch
44	        {
45	            // Safety net (SPEC §6): any exception inside a step becomes a no-op for that step.
46	        }
47	    }
48	
49	    private static void Replace(StepSpec step, OpContext ctx)
50	    {
51	        string find = step.GetString("find", "");
52	        string replaceWith = step.GetString("replaceWith", "");
53	        bool regex = step.GetBool("regex", false);
54	        bool ignoreCase = step.GetBool("ignoreCase", false);
55	
56	        if (find == "") return; // no-op
57	
58	        if (!regex)
59	        {
60	            var comparison = ignoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
61	            ctx.Target = ctx.Target.Replace(find, replaceWith, comparison);
62	            return;
63	        }
64	
65	        try
66	        {
67	            var options = RegexOptions.CultureInvariant | (ignoreCase ? RegexOptions.IgnoreCase : RegexOptions.None);
68	            var re = new Regex(find, options, RegexTimeout);
69	            ctx.Target = re.Replace(ctx.Target, replaceWith);
70	        }
71	        catch (ArgumentException)
72	        {
73	            // invalid pattern -> no-op
74	        }
75	        catch (RegexMatchTimeoutException)
76	        {
77	            // no-op
78	        }
79	    }
80	
81	    private static void Insert(StepSpec step, OpContext ctx)
82	    {
83	        string text = step.GetString("text", "");
84	        string position = step.GetString("position", "prefix");
85	        int index = step.GetInt("index", 0);
86	
87	        switch (position)
88	        {
89	            case "suffix":
90	                ctx.Target = ctx.Target + text;
91	                break;
92	            case "index":
93	                int i = Math.Clamp(index, 0, ctx.Target.Length);
94	                ctx.Target = ctx.Target.Insert(i, text);
95	                break;
96	            case "prefix":
97	            default:
98	                ctx.Target = text + ctx.Target;
99	                break;
100	        }
101	    }
102	
103	    private static void Remove(StepSpec step, OpContext ctx)
104	    {
105	        int len = ctx.Target.Length;
106	        int from = Math.Clamp(step.GetInt("from", 0), 0, len);
107	        int count = Math.Clamp(step.GetInt("count", 0), 0, len - from);
108	        ctx.Target = ctx.Target.Remove(from, count);
109	    }
110	
111	    private static readonly Regex SequenceTokenRegex = new(@"\{n:(0+)\}", RegexOptions.CultureInvariant);
112	
113	    private static void Sequence(StepSpec step, OpContext ctx)
114	    {
115	        string pattern = step.GetString("pattern", "{n:000}_");
116	        int start = step.GetInt("start", 1);
117	        int stepVal = step.GetInt("step", 1);
118	        string position = step.GetString("position", "prefix");
119	
120	        long counter = (long)start + (long)ctx.Index * stepVal;
121	
122	        string text = SequenceTokenRegex.Replace(pattern, m =>
123	        {
124	            int padLen = m.Groups[1].Value.Length;
125	            return counter.ToString(new string('0', padLen), CultureInfo.InvariantCulture);
126	        });
127	
128	        ctx.Target = position == "suffix" ? ctx.Target + text : text + ctx.Target;
129	    }
130	
131	    private static void CaseOp(StepSpec step, OpContext ctx)
132	    {
133	        string mode = step.GetString("mode", "upper");
134	        switch (mode)
135	        {
136	            case "upper":
137	                ctx.Target = ctx.Target.ToUpperInvariant();
138	                break;
139	            case "lower":
140	                ctx.Target = ctx.Target.ToLowerInvariant();
141	                break;
142	            case "title":
143	                ctx.Target = TitleCase(ctx.Target);
144	                break;
145	            default:
146	                // unrecognised mode -> no-op
147	                break;
148	        }
149	    }
150	
151	    private static string TitleCase(string s)
152	    {
153	        var sb = new StringBuilder(s.Length);
154	        int i = 0;
155	        while (i < s.Length)
156	        {
157	            if (char.IsLetter(s[i]))
158	            {
159	                int start = i;
160	                while (i < s.Length && char.IsLetter(s[i])) i++;
161	                var run = s.Substring(start, i - start);
162	                sb.Append(char.ToUpperInvariant(run[0]));
163	                if (run.Length > 1) sb.Append(run.Substring(1).ToLowerInvariant());
164	            }
165	            else
166	            {
167	                sb.Append(s[i]);
168	                i++;
169	            }
170	        }
171	        return sb.ToString();
172	    }
173	
174	    private static string? ApplyExtensionMode(string mode, string currentExt, string value)
175	    {
176	        switch (mode)
177	        {
178	            case "lower": return currentExt.ToLowerInvariant();
179	            case "upper": return currentExt.ToUpperInvariant();
180	            case "set": return value;
181	            default: return null; // unrecognised -> no-op
182	        }
183	    }
184	
185	    private static void Extension(StepSpec step, OpContext ctx)
186	    {
187	        string mode = step.GetString("mode", "lower");
188	        string value = step.GetString("value", "txt");
189	
190	        if (ctx.ApplyTo == ApplyTo.Name)
191	        {
192	            var e2 = ApplyExtensionMode(mode, ctx.CurrentExtension, value);
193	            if (e2 is null) return;
194	            ctx.CurrentExtension = e2;
195	        }
196	        else
197	        {
198	            var (b, e) = NameParts.Split(ctx.Target);
199	            var e2 = ApplyExtensionMode(mode, e, value);
200	            if (e2 is null) return;
201	            ctx.Target = e2 == "" ? b : b + "." + e2;
202	        }
203	    }
204	
205	    private static void Pad(StepSpec step, OpContext ctx)
206	    {
207	        int length = step.GetInt("length", 0);
208	        string fill = step.GetString("fill", "_");
209	        string side = step.GetString("side", "left");
210	
211	        if (fill.Length != 1) return;
212	        if (ctx.Target.Length >= length) return;
213	
214	        int need = length - ctx.Target.Length;
215	        string padding = new string(fill[0], need);
216	        ctx.Target = side == "left" ? padding + ctx.Target : ctx.Target + padding;
217	    }
218	
219	    private static void Trim(StepSpec step, OpContext ctx)
220	    {
221	        string chars = step.GetString("chars", " _-");
222	        string side = step.GetString("side", "both");
223	
224	        if (chars == "") return;
225	
226	        var set = new HashSet<char>(chars);
227	        string effSide = (side == "left" || side == "right") ? side : "both";
228	
229	        string t = ctx.Target;
230	        int start = 0;
231	        int end = t.Length;
232	
233	        if (effSide == "left" || effSide == "both")
234	        {
235	            while (start < end && set.Contains(t[start])) start++;
236	        }
237	        if (effSide == "right" || effSide == "both")
238	        {
239	            while (end > start && set.Contains(t[end - 1])) end--;
240	        }
241	
242	        ctx.Target = t.Substring(start, end - start);
243	    }
244	
245	    private static void Slug(StepSpec step, OpContext ctx)
246	    {
247	        string separator = step.GetString("separator", "-");
248	        string s = ctx.Target.ToLowerInvariant();
249	
250	        var sb = new StringBuilder();
251	        bool inRun = false;
252	        foreach (char ch in s)
253	        {
254	            bool isAlnum = (ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9');
255	            if (isAlnum)
256	            {
257	                sb.Append(ch);
258	                inRun = false;
259	            }
260	            else
261	            {
262	                if (!inRun)
263	                {
264	                    sb.Append(separator);
265	                    inRun = true;
266	                }
267	            }
268	        }
269	
270	        string result = sb.ToString();
271	        if (separator != "")
272	        {
273	            while (result.StartsWith(separator, StringComparison.Ordinal))
274	                result = result.Substring(separator.Length);
275	            while (result.EndsWith(separator, StringComparison.Ordinal))
276	                result = result.Substring(0, result.Length - separator.Length);
277	        }
278	
279	        ctx.Target = result;
280	    }
281	
282	    private static void Translate(StepSpec step, OpContext ctx)
283	    {
284	        string from = step.GetString("from", "");
285	        string to = step.GetString("to", "");
286	
287	        var map = new Dictionary<char, char?>();
288	        for (int k = 0; k < from.Length; k++)
289	        {
290	            char fc = from[k];
291	            if (map.ContainsKey(fc)) continue; // first mapping wins
292	            map[fc] = k < to.Length ? to[k] : (char?)null;
293	        }
294	
295	        var sb = new StringBuilder(ctx.Target.Length);
296	        foreach (char c in ctx.Target)
297	        {
298	            if (map.TryGetValue(c, out var mapped))
299	            {
300	                if (mapped.HasValue) sb.Append(mapped.Value);
301	                // else: deleted
302	            }
303	            else
304	            {
305	                sb.Append(c);
306	            }
307	        }
308	
309	        ctx.Target = sb.ToString();
310	    }
311	
312	    private static void NumberFormat(StepSpec step, OpContext ctx)
313	    {
314	        int width = step.GetInt("width", 4);
315	        string target = ctx.Target;
316	
317	        int start = -1;
318	        int len = 0;
319	        int i = 0;
320	        while (i < target.Length)
321	        {
322	            if (target[i] >= '0' && target[i] <= '9')
323	            {
324	                start = i;
325	                int j = i;
326	                while (j < target.Length && target[j] >= '0' && target[j] <= '9') j++;
327	                len = j - i;
328	                break;
329	            }
330	            i++;
331	        }
332	
333	        if (start == -1) return; // no digit run -> no-op
334	        if (len >= width) return; // no-op
335	
336	        string run = target.Substring(start, len);
337	        string padded = run.PadLeft(width, '0');
338	        ctx.Target = target.Substring(0, start) + padded + target.Substring(start + len);
339	    }
340	
341	    private static void Extract(StepSpec step, OpContext ctx)
342	    {
343	        string pattern = step.GetString("pattern", "");
344	        int group = step.GetInt("group", 0);
345	
346	        try
347	        {
348	            var m = Regex.Match(ctx.Target, pattern, RegexOptions.CultureInvariant, RegexTimeout);
349	            if (!m.Success)
350	            {
351	                ctx.Target = "";
352	                return;
353	            }
354	            if (group < 0 || group >= m.Groups.Count)
355	            {
356	                ctx.Target = "";
357	                return;
358	            }
359	            ctx.Target = m.Groups[group].Value;
360	        }
361	        catch (ArgumentException)
362	        {
363	            // invalid pattern -> no-op
364	        }
365	        catch (RegexMatchTimeoutException)
366	        {
367	            // no-op
368	        }
369	    }
370	
371	    private static readonly Regex TemplateSequenceToken = new(@"^n:(0+)$", RegexOptions.CultureInvariant);
372	
373	    private static void Template(StepSpec step, OpContext ctx)
374	    {
375	        string format = step.GetString("format", "");
376	        string cur = ctx.Target; // captured before substituting
377	
378	        var sb = new StringBuilder();
379	        int i = 0;
380	        while (i < format.Length)
381	        {
382	            char c = format[i];
383	            if (c == '{')
384	            {
385	                int closeIdx = format.IndexOf('}', i + 1);
386	                if (closeIdx == -1)
387	                {
388	                    sb.Append(format.Substring(i));
389	                    break;
390	                }
391	
392	                string token = format.Substring(i + 1, closeIdx - i - 1);
393	                var nm = TemplateSequenceToken.Match(token);
394	                if (token == "name")
395	                {
396	                    sb.Append(cur);
397	                }
398	                else if (token == "ext")
399	                {
400	                    sb.Append(ctx.OriginalExtension);
401	                }
402	                else if (token == "len")
403	                {
404	                    sb.Append(cur.Length.ToString(CultureInfo.InvariantCulture));
405	                }
406	                else if (nm.Success)
407	                {
408	                    int padLen = nm.Groups[1].Value.Length;
409	                    sb.Append((ctx.Index + 1).ToString(new string('0', padLen), CultureInfo.InvariantCulture));
410	                }
411	                else
412	                {
413	                    sb.Append('{').Append(token).Append('}');
414	                }
415	
416	                i = closeIdx + 1;
417	            }
418	            else
419	            {
420	                sb.Append(c);
421	                i++;
422	            }
423	        }
424	
425	        ctx.Target = sb.ToString();
426	    }
427	
428	    private static void DedupeChars(StepSpec step, OpContext ctx)
429	    {
430	        var sb = new StringBuilder(ctx.Target.Length);
431	        char? prev = null;
432	        foreach (char c in ctx.Target)
433	        {
434	            if (prev is null || prev.Value != c) sb.Append(c);
435	            prev = c;
436	        }
437	        ctx.Target = sb.ToString();
438	    }
439	}
