using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

/// <summary>
/// The 14 op implementations and the step dispatcher.
/// Every op is a safety-netted no-op on any unexpected exception (SPEC §6):
/// each Apply* method computes its result locally and only assigns it to
/// ctx.Target/ctx.CurrentExtension once fully computed, so a thrown exception
/// never leaves a partially-mutated target.
/// </summary>
public static class Operations
{
    private static readonly TimeSpan RegexTimeout = TimeSpan.FromSeconds(1);

    public static void Apply(StepSpec step, OpContext ctx)
    {
        try
        {
            switch (step.Op)
            {
                case "replace": Replace(step, ctx); break;
                case "insert": Insert(step, ctx); break;
                case "remove": Remove(step, ctx); break;
                case "sequence": Sequence(step, ctx); break;
                case "case": CaseOp(step, ctx); break;
                case "extension": Extension(step, ctx); break;
                case "pad": Pad(step, ctx); break;
                case "trim": Trim(step, ctx); break;
                case "slug": Slug(step, ctx); break;
                case "translate": Translate(step, ctx); break;
                case "numberFormat": NumberFormat(step, ctx); break;
                case "extract": Extract(step, ctx); break;
                case "template": Template(step, ctx); break;
                case "dedupeChars": DedupeChars(step, ctx); break;
                default:
                    // Unknown op: treated as a no-op, still recorded in the trace by the caller.
                    break;
            }
        }
        catch
        {
            // Safety net (SPEC §6): any exception inside a step becomes a no-op for that step.
        }
    }

    private static void Replace(StepSpec step, OpContext ctx)
    {
        string find = step.GetString("find", "");
        string replaceWith = step.GetString("replaceWith", "");
        bool regex = step.GetBool("regex", false);
        bool ignoreCase = step.GetBool("ignoreCase", false);

        if (find == "") return; // no-op

        if (!regex)
        {
            var comparison = ignoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
            ctx.Target = ctx.Target.Replace(find, replaceWith, comparison);
            return;
        }

        try
        {
            var options = RegexOptions.CultureInvariant | (ignoreCase ? RegexOptions.IgnoreCase : RegexOptions.None);
            var re = new Regex(find, options, RegexTimeout);
            ctx.Target = re.Replace(ctx.Target, replaceWith);
        }
        catch (ArgumentException)
        {
            // invalid pattern -> no-op
        }
        catch (RegexMatchTimeoutException)
        {
            // no-op
        }
    }

    private static void Insert(StepSpec step, OpContext ctx)
    {
        string text = step.GetString("text", "");
        string position = step.GetString("position", "prefix");
        int index = step.GetInt("index", 0);

        switch (position)
        {
            case "suffix":
                ctx.Target = ctx.Target + text;
                break;
            case "index":
                int i = Math.Clamp(index, 0, ctx.Target.Length);
                ctx.Target = ctx.Target.Insert(i, text);
                break;
            case "prefix":
            default:
                ctx.Target = text + ctx.Target;
                break;
        }
    }

    private static void Remove(StepSpec step, OpContext ctx)
    {
        int len = ctx.Target.Length;
        int from = Math.Clamp(step.GetInt("from", 0), 0, len);
        int count = Math.Clamp(step.GetInt("count", 0), 0, len - from);
        ctx.Target = ctx.Target.Remove(from, count);
    }

    private static readonly Regex SequenceTokenRegex = new(@"\{n:(0+)\}", RegexOptions.CultureInvariant);

    private static void Sequence(StepSpec step, OpContext ctx)
    {
        string pattern = step.GetString("pattern", "{n:000}_");
        int start = step.GetInt("start", 1);
        int stepVal = step.GetInt("step", 1);
        string position = step.GetString("position", "prefix");

        long counter = (long)start + (long)ctx.Index * stepVal;

        string text = SequenceTokenRegex.Replace(pattern, m =>
        {
            int padLen = m.Groups[1].Value.Length;
            return counter.ToString(new string('0', padLen), CultureInfo.InvariantCulture);
        });

        ctx.Target = position == "suffix" ? ctx.Target + text : text + ctx.Target;
    }

    private static void CaseOp(StepSpec step, OpContext ctx)
    {
        string mode = step.GetString("mode", "upper");
        switch (mode)
        {
            case "upper":
                ctx.Target = ctx.Target.ToUpperInvariant();
                break;
            case "lower":
                ctx.Target = ctx.Target.ToLowerInvariant();
                break;
            case "title":
                ctx.Target = TitleCase(ctx.Target);
                break;
            default:
                // unrecognised mode -> no-op
                break;
        }
    }

    private static string TitleCase(string s)
    {
        var sb = new StringBuilder(s.Length);
        int i = 0;
        while (i < s.Length)
        {
            if (char.IsLetter(s[i]))
            {
                int start = i;
                while (i < s.Length && char.IsLetter(s[i])) i++;
                var run = s.Substring(start, i - start);
                sb.Append(char.ToUpperInvariant(run[0]));
                if (run.Length > 1) sb.Append(run.Substring(1).ToLowerInvariant());
            }
            else
            {
                sb.Append(s[i]);
                i++;
            }
        }
        return sb.ToString();
    }

    private static string? ApplyExtensionMode(string mode, string currentExt, string value)
    {
        switch (mode)
        {
            case "lower": return currentExt.ToLowerInvariant();
            case "upper": return currentExt.ToUpperInvariant();
            case "set": return value;
            default: return null; // unrecognised -> no-op
        }
    }

    private static void Extension(StepSpec step, OpContext ctx)
    {
        string mode = step.GetString("mode", "lower");
        string value = step.GetString("value", "txt");

        if (ctx.ApplyTo == ApplyTo.Name)
        {
            var e2 = ApplyExtensionMode(mode, ctx.CurrentExtension, value);
            if (e2 is null) return;
            ctx.CurrentExtension = e2;
        }
        else
        {
            var (b, e) = NameParts.Split(ctx.Target);
            var e2 = ApplyExtensionMode(mode, e, value);
            if (e2 is null) return;
            ctx.Target = e2 == "" ? b : b + "." + e2;
        }
    }

    private static void Pad(StepSpec step, OpContext ctx)
    {
        int length = step.GetInt("length", 0);
        string fill = step.GetString("fill", "_");
        string side = step.GetString("side", "left");

        if (fill.Length != 1) return;
        if (ctx.Target.Length >= length) return;

        int need = length - ctx.Target.Length;
        string padding = new string(fill[0], need);
        ctx.Target = side == "left" ? padding + ctx.Target : ctx.Target + padding;
    }

    private static void Trim(StepSpec step, OpContext ctx)
    {
        string chars = step.GetString("chars", " _-");
        string side = step.GetString("side", "both");

        if (chars == "") return;

        var set = new HashSet<char>(chars);
        string effSide = (side == "left" || side == "right") ? side : "both";

        string t = ctx.Target;
        int start = 0;
        int end = t.Length;

        if (effSide == "left" || effSide == "both")
        {
            while (start < end && set.Contains(t[start])) start++;
        }
        if (effSide == "right" || effSide == "both")
        {
            while (end > start && set.Contains(t[end - 1])) end--;
        }

        ctx.Target = t.Substring(start, end - start);
    }

    private static void Slug(StepSpec step, OpContext ctx)
    {
        string separator = step.GetString("separator", "-");
        string s = ctx.Target.ToLowerInvariant();

        var sb = new StringBuilder();
        bool inRun = false;
        foreach (char ch in s)
        {
            bool isAlnum = (ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9');
            if (isAlnum)
            {
                sb.Append(ch);
                inRun = false;
            }
            else
            {
                if (!inRun)
                {
                    sb.Append(separator);
                    inRun = true;
                }
            }
        }

        string result = sb.ToString();
        if (separator != "")
        {
            while (result.StartsWith(separator, StringComparison.Ordinal))
                result = result.Substring(separator.Length);
            while (result.EndsWith(separator, StringComparison.Ordinal))
                result = result.Substring(0, result.Length - separator.Length);
        }

        ctx.Target = result;
    }

    private static void Translate(StepSpec step, OpContext ctx)
    {
        string from = step.GetString("from", "");
        string to = step.GetString("to", "");

        var map = new Dictionary<char, char?>();
        for (int k = 0; k < from.Length; k++)
        {
            char fc = from[k];
            if (map.ContainsKey(fc)) continue; // first mapping wins
            map[fc] = k < to.Length ? to[k] : (char?)null;
        }

        var sb = new StringBuilder(ctx.Target.Length);
        foreach (char c in ctx.Target)
        {
            if (map.TryGetValue(c, out var mapped))
            {
                if (mapped.HasValue) sb.Append(mapped.Value);
                // else: deleted
            }
            else
            {
                sb.Append(c);
            }
        }

        ctx.Target = sb.ToString();
    }

    private static void NumberFormat(StepSpec step, OpContext ctx)
    {
        int width = step.GetInt("width", 4);
        string target = ctx.Target;

        int start = -1;
        int len = 0;
        int i = 0;
        while (i < target.Length)
        {
            if (target[i] >= '0' && target[i] <= '9')
            {
                start = i;
                int j = i;
                while (j < target.Length && target[j] >= '0' && target[j] <= '9') j++;
                len = j - i;
                break;
            }
            i++;
        }

        if (start == -1) return; // no digit run -> no-op
        if (len >= width) return; // no-op

        string run = target.Substring(start, len);
        string padded = run.PadLeft(width, '0');
        ctx.Target = target.Substring(0, start) + padded + target.Substring(start + len);
    }

    private static void Extract(StepSpec step, OpContext ctx)
    {
        string pattern = step.GetString("pattern", "");
        int group = step.GetInt("group", 0);

        try
        {
            var m = Regex.Match(ctx.Target, pattern, RegexOptions.CultureInvariant, RegexTimeout);
            if (!m.Success)
            {
                ctx.Target = "";
                return;
            }
            if (group < 0 || group >= m.Groups.Count)
            {
                ctx.Target = "";
                return;
            }
            ctx.Target = m.Groups[group].Value;
        }
        catch (ArgumentException)
        {
            // invalid pattern -> no-op
        }
        catch (RegexMatchTimeoutException)
        {
            // no-op
        }
    }

    private static readonly Regex TemplateSequenceToken = new(@"^n:(0+)$", RegexOptions.CultureInvariant);

    private static void Template(StepSpec step, OpContext ctx)
    {
        string format = step.GetString("format", "");
        string cur = ctx.Target; // captured before substituting

        var sb = new StringBuilder();
        int i = 0;
        while (i < format.Length)
        {
            char c = format[i];
            if (c == '{')
            {
                int closeIdx = format.IndexOf('}', i + 1);
                if (closeIdx == -1)
                {
                    sb.Append(format.Substring(i));
                    break;
                }

                string token = format.Substring(i + 1, closeIdx - i - 1);
                var nm = TemplateSequenceToken.Match(token);
                if (token == "name")
                {
                    sb.Append(cur);
                }
                else if (token == "ext")
                {
                    sb.Append(ctx.OriginalExtension);
                }
                else if (token == "len")
                {
                    sb.Append(cur.Length.ToString(CultureInfo.InvariantCulture));
                }
                else if (nm.Success)
                {
                    int padLen = nm.Groups[1].Value.Length;
                    sb.Append((ctx.Index + 1).ToString(new string('0', padLen), CultureInfo.InvariantCulture));
                }
                else
                {
                    sb.Append('{').Append(token).Append('}');
                }

                i = closeIdx + 1;
            }
            else
            {
                sb.Append(c);
                i++;
            }
        }

        ctx.Target = sb.ToString();
    }

    private static void DedupeChars(StepSpec step, OpContext ctx)
    {
        var sb = new StringBuilder(ctx.Target.Length);
        char? prev = null;
        foreach (char c in ctx.Target)
        {
            if (prev is null || prev.Value != c) sb.Append(c);
            prev = c;
        }
        ctx.Target = sb.ToString();
    }
}

