namespace BatchRenameStudio.Core;

/// <summary>
/// Single computation feeding BOTH the plan and trace contracts, so --plan and
/// --explain can never disagree.
/// </summary>
public sealed class EngineResult
{
    public IReadOnlyList<TraceFile> Files { get; }
    private readonly IReadOnlyList<string> _reasons;

    internal EngineResult(IReadOnlyList<TraceFile> files, IReadOnlyList<string> reasons)
    {
        Files = files;
        _reasons = reasons;
    }

    public PlanResult ToPlan()
    {
        var summary = new PlanSummary { Total = Files.Count };
        var items = new List<PlanItem>(Files.Count);

        for (int i = 0; i < Files.Count; i++)
        {
            var f = Files[i];
            items.Add(new PlanItem
            {
                Original = f.Original,
                Proposed = f.Proposed,
                Status = f.Status,
                Reason = _reasons[i],
            });

            switch (f.Status)
            {
                case "ok": summary.Ok++; break;
                case "collision": summary.Collision++; break;
                case "unchanged": summary.Unchanged++; break;
                case "invalid": summary.Invalid++; break;
            }
        }

        return new PlanResult { Items = items, Summary = summary };
    }

    public TraceResult ToTrace()
    {
        return new TraceResult { Files = new List<TraceFile>(Files) };
    }
}

public static class RenameEngine
{
    public static EngineResult Run(IReadOnlyList<FileEntry> files, RuleSet rules)
    {
        List<FileEntry> sorted = rules.Sort switch
        {
            SortMode.Created => files.OrderBy(f => f.CreatedUtc).ThenBy(f => f.Name, StringComparer.Ordinal).ToList(),
            SortMode.Modified => files.OrderBy(f => f.ModifiedUtc).ThenBy(f => f.Name, StringComparer.Ordinal).ToList(),
            _ => files.OrderBy(f => f.Name, StringComparer.Ordinal).ToList(),
        };

        var traceFiles = new List<TraceFile>(sorted.Count);

        for (int i = 0; i < sorted.Count; i++)
        {
            var file = sorted[i];
            var (baseName, ext) = NameParts.Split(file.Name);
            string initialTarget = rules.ApplyTo == ApplyTo.Name ? baseName : file.Name;
            var ctx = new OpContext(initialTarget, ext, ext, i, rules.ApplyTo);

            var steps = new List<TraceStep>(rules.Steps.Count);
            for (int s = 0; s < rules.Steps.Count; s++)
            {
                var step = rules.Steps[s];
                string before = ctx.Target;
                Operations.Apply(step, ctx);
                string after = ctx.Target;
                steps.Add(new TraceStep { Index = s, Op = step.Op, Before = before, After = after });
            }

            string proposed = rules.ApplyTo == ApplyTo.Name
                ? NameParts.Combine(ctx.Target, ctx.CurrentExtension)
                : ctx.Target;

            traceFiles.Add(new TraceFile
            {
                Original = file.Name,
                Steps = steps,
                Proposed = proposed,
                Status = "", // filled in the classification pass below
            });
        }

        // --- Classification pass (§5): needs every item's proposal, so it runs second. ---
        var reasons = new List<string>(traceFiles.Count);

        var existingByCi = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var f in sorted) existingByCi[f.Name] = f.Name;

        var proposedCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var tf in traceFiles)
        {
            proposedCounts[tf.Proposed] = proposedCounts.GetValueOrDefault(tf.Proposed) + 1;
        }

        for (int i = 0; i < traceFiles.Count; i++)
        {
            var tf = traceFiles[i];
            string original = tf.Original;
            string proposed = tf.Proposed;
            string status;
            string reason;

            if (StatusRules.IsInvalid(proposed, out var invalidReason))
            {
                status = "invalid";
                reason = invalidReason;
            }
            else
            {
                bool collidesExisting = existingByCi.TryGetValue(proposed, out var matched) &&
                                         !string.Equals(matched, original, StringComparison.Ordinal);
                bool collidesOtherItem = proposedCounts[proposed] > 1;

                if (collidesExisting)
                {
                    status = "collision";
                    reason = "target already exists";
                }
                else if (collidesOtherItem)
                {
                    status = "collision";
                    reason = "duplicate proposed name";
                }
                else if (string.Equals(proposed, original, StringComparison.Ordinal))
                {
                    status = "unchanged";
                    reason = "";
                }
                else
                {
                    status = "ok";
                    reason = "";
                }
            }

            tf.Status = status;
            reasons.Add(reason);
        }

        return new EngineResult(traceFiles, reasons);
    }

    public static EngineResult RunFolder(string directory, RuleSet rules)
    {
        var files = FolderScanner.Scan(directory);
        return Run(files, rules);
    }
}

