namespace BatchRenameStudio.Core;

/// <summary>
/// Rule 2 (split) and rule 6 (reassembly) helpers.
/// </summary>
public static class NameParts
{
    /// <summary>
    /// dot = name.LastIndexOf('.')
    /// if (dot > 0) { base = name[0..dot]; ext = name[(dot+1)..]; }  // ext carries NO dot
    /// else         { base = name;         ext = ""; }
    /// </summary>
    public static (string BaseName, string Ext) Split(string name)
    {
        int dot = name.LastIndexOf('.');
        if (dot > 0)
        {
            return (name.Substring(0, dot), name.Substring(dot + 1));
        }
        return (name, "");
    }

    /// <summary>
    /// applyTo = Name reassembly: proposed = ext == "" ? target : target + "." + ext
    /// </summary>
    public static string Combine(string baseName, string ext)
    {
        return ext == "" ? baseName : baseName + "." + ext;
    }
}
namespace BatchRenameStudio.Core;

/// <summary>
/// SPEC §5 — status classification (rule 7: first match wins). This file only
/// implements the "invalid" check (structural validity of the proposed name);
/// collision/unchanged/ok are contextual (need sibling items) and are handled
/// in RenameEngine.
/// </summary>
public static class StatusRules
{
    private static readonly char[] InvalidChars = { '<', '>', ':', '"', '/', '\\', '|', '?', '*' };

    private static readonly HashSet<string> ReservedNames = new(StringComparer.OrdinalIgnoreCase)
    {
        "CON", "PRN", "AUX", "NUL",
        "COM1", "COM2", "COM3", "COM4", "COM5", "COM6", "COM7", "COM8", "COM9",
        "LPT1", "LPT2", "LPT3", "LPT4", "LPT5", "LPT6", "LPT7", "LPT8", "LPT9",
    };

    public static bool IsInvalid(string proposed, out string reason)
    {
        if (proposed.Length == 0)
        {
            reason = "empty name";
            return true;
        }

        if (proposed.Length > 255)
        {
            reason = "name too long";
            return true;
        }

        foreach (char c in proposed)
        {
            if (Array.IndexOf(InvalidChars, c) >= 0 || c < ' ')
            {
                reason = "contains invalid character";
                return true;
            }
        }

        var (baseName, _) = NameParts.Split(proposed);
        if (ReservedNames.Contains(baseName))
        {
            reason = "reserved device name";
            return true;
        }

        reason = "";
        return false;
    }
}
namespace BatchRenameStudio.Core;

public sealed record FileEntry(string Name, DateTime CreatedUtc, DateTime ModifiedUtc);

public static class FolderScanner
{
    /// <summary>
    /// Regular files DIRECTLY inside dir, non-recursive, directories excluded.
    /// Reparse points / symlinks to files are included; junctions & dirs are not.
    /// Directory.EnumerateFiles already implements exactly this on Windows: it
    /// filters purely on the DIRECTORY attribute, which a file-symlink reparse
    /// point does not carry but a directory-junction reparse point does.
    /// </summary>
    public static List<FileEntry> Scan(string directory)
    {
        var result = new List<FileEntry>();
        foreach (var path in Directory.EnumerateFiles(directory, "*", SearchOption.TopDirectoryOnly))
        {
            var name = Path.GetFileName(path);
            var created = File.GetCreationTimeUtc(path);
            var modified = File.GetLastWriteTimeUtc(path);
            result.Add(new FileEntry(name, created, modified));
        }
        return result;
    }
}
using System.Text;
using System.Text.Json;

namespace BatchRenameStudio.Core;

public static class JsonIo
{
    public static string SerializePlan(PlanResult plan)
    {
        using var stream = new MemoryStream();
        using (var writer = new Utf8JsonWriter(stream, new JsonWriterOptions { Indented = true }))
        {
            writer.WriteStartObject();
            writer.WriteNumber("schemaVersion", plan.SchemaVersion);

            writer.WriteStartArray("items");
            foreach (var item in plan.Items)
            {
                writer.WriteStartObject();
                writer.WriteString("original", item.Original);
                writer.WriteString("proposed", item.Proposed);
                writer.WriteString("status", item.Status);
                writer.WriteString("reason", item.Reason);
                writer.WriteEndObject();
            }
            writer.WriteEndArray();

            writer.WriteStartObject("summary");
            writer.WriteNumber("total", plan.Summary.Total);
            writer.WriteNumber("ok", plan.Summary.Ok);
            writer.WriteNumber("collision", plan.Summary.Collision);
            writer.WriteNumber("unchanged", plan.Summary.Unchanged);
            writer.WriteNumber("invalid", plan.Summary.Invalid);
            writer.WriteEndObject();

            writer.WriteEndObject();
        }
        return Encoding.UTF8.GetString(stream.ToArray());
    }

    public static string SerializeTrace(TraceResult trace)
    {
        using var stream = new MemoryStream();
        using (var writer = new Utf8JsonWriter(stream, new JsonWriterOptions { Indented = true }))
        {
            writer.WriteStartObject();
            writer.WriteNumber("schemaVersion", trace.SchemaVersion);

            writer.WriteStartArray("files");
            foreach (var f in trace.Files)
            {
                writer.WriteStartObject();
                writer.WriteString("original", f.Original);

                writer.WriteStartArray("steps");
                foreach (var s in f.Steps)
                {
                    writer.WriteStartObject();
                    writer.WriteNumber("index", s.Index);
                    writer.WriteString("op", s.Op);
                    writer.WriteString("before", s.Before);
                    writer.WriteString("after", s.After);
                    writer.WriteEndObject();
                }
                writer.WriteEndArray();

                writer.WriteString("proposed", f.Proposed);
                writer.WriteString("status", f.Status);
                writer.WriteEndObject();
            }
            writer.WriteEndArray();

            writer.WriteEndObject();
        }
        return Encoding.UTF8.GetString(stream.ToArray());
    }

    /// <summary>
    /// Writes UTF8Encoding(encoderShouldEmitUTF8Identifier: false) — no BOM.
    /// Creates the output directory if it does not exist.
    /// </summary>
    public static void WriteUtf8NoBom(string path, string content)
    {
        var dir = Path.GetDirectoryName(path);
        if (!string.IsNullOrEmpty(dir) && !Directory.Exists(dir))
        {
            Directory.CreateDirectory(dir);
        }

        var encoding = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false);
        File.WriteAllText(path, content, encoding);
    }
}

