using System.Globalization;
using System.Text.Json;
using System.Text.Json.Nodes;

namespace BatchRenameStudio.Core;

public enum ApplyTo { Name, NameAndExtension }
public enum SortMode { Name, Created, Modified }

/// <summary>
/// A rule step is a property bag: op name + loosely typed parameters.
/// Parameter values are normalised to string | long | bool | null.
/// </summary>
public sealed class StepSpec
{
    public string Op { get; set; }
    public IDictionary<string, object?> Params { get; } = new Dictionary<string, object?>();

    public StepSpec(string op)
    {
        Op = op;
    }

    public string GetString(string key, string fallback = "")
    {
        if (!Params.TryGetValue(key, out var v) || v is null) return fallback;
        return v switch
        {
            string s => s,
            long l => l.ToString(CultureInfo.InvariantCulture),
            bool b => b ? "true" : "false",
            _ => fallback,
        };
    }

    public int GetInt(string key, int fallback = 0)
    {
        if (!Params.TryGetValue(key, out var v) || v is null) return fallback;
        switch (v)
        {
            case long l:
                return unchecked((int)l);
            case int i:
                return i;
            case string s:
                if (long.TryParse(s, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed))
                    return unchecked((int)parsed);
                return fallback;
            default:
                return fallback;
        }
    }

    public bool GetBool(string key, bool fallback = false)
    {
        if (!Params.TryGetValue(key, out var v) || v is null) return fallback;
        switch (v)
        {
            case bool b:
                return b;
            case string s:
                if (bool.TryParse(s, out var parsed)) return parsed;
                return fallback;
            case long l:
                return l != 0;
            default:
                return fallback;
        }
    }

    public void Set(string key, object? value)
    {
        Params[key] = value;
    }

    public StepSpec Clone()
    {
        var clone = new StepSpec(Op);
        foreach (var kv in Params)
        {
            clone.Params[kv.Key] = kv.Value;
        }
        return clone;
    }

    public string Describe()
    {
        if (Params.Count == 0) return Op;
        var parts = new List<string>();
        foreach (var kv in Params)
        {
            var v = kv.Value switch
            {
                null => "",
                string s => s,
                bool b => b ? "true" : "false",
                long l => l.ToString(CultureInfo.InvariantCulture),
                _ => kv.Value.ToString() ?? "",
            };
            parts.Add($"{kv.Key}={v}");
        }
        return $"{Op}: {string.Join(", ", parts)}";
    }
}

public sealed class RuleSet
{
    public ApplyTo ApplyTo { get; set; } = ApplyTo.Name;
    public SortMode Sort { get; set; } = SortMode.Name;
    public List<StepSpec> Steps { get; } = new();

    public RuleSet Clone()
    {
        var clone = new RuleSet { ApplyTo = ApplyTo, Sort = Sort };
        foreach (var step in Steps)
        {
            clone.Steps.Add(step.Clone());
        }
        return clone;
    }

    public static RuleSet FromJson(string json)
    {
        var docOptions = new JsonDocumentOptions
        {
            AllowTrailingCommas = true,
            CommentHandling = JsonCommentHandling.Skip,
        };

        using var doc = JsonDocument.Parse(json, docOptions);
        var root = doc.RootElement;
        var rules = new RuleSet();

        if (root.ValueKind != JsonValueKind.Object)
        {
            return rules;
        }

        if (TryGetPropertyCaseInsensitive(root, "applyTo", out var applyToEl) &&
            applyToEl.ValueKind == JsonValueKind.String)
        {
            var s = applyToEl.GetString();
            rules.ApplyTo = string.Equals(s, "nameAndExtension", StringComparison.OrdinalIgnoreCase)
                ? ApplyTo.NameAndExtension
                : ApplyTo.Name;
        }

        if (TryGetPropertyCaseInsensitive(root, "sort", out var sortEl) &&
            sortEl.ValueKind == JsonValueKind.String)
        {
            var s = sortEl.GetString();
            if (string.Equals(s, "created", StringComparison.OrdinalIgnoreCase))
                rules.Sort = SortMode.Created;
            else if (string.Equals(s, "modified", StringComparison.OrdinalIgnoreCase))
                rules.Sort = SortMode.Modified;
            else
                rules.Sort = SortMode.Name;
        }

        if (TryGetPropertyCaseInsensitive(root, "steps", out var stepsEl) &&
            stepsEl.ValueKind == JsonValueKind.Array)
        {
            foreach (var stepEl in stepsEl.EnumerateArray())
            {
                try
                {
                    if (stepEl.ValueKind != JsonValueKind.Object) continue;

                    string op = "";
                    if (TryGetPropertyCaseInsensitive(stepEl, "op", out var opEl) &&
                        opEl.ValueKind == JsonValueKind.String)
                    {
                        op = opEl.GetString() ?? "";
                    }

                    var step = new StepSpec(op);
                    foreach (var prop in stepEl.EnumerateObject())
                    {
                        if (string.Equals(prop.Name, "op", StringComparison.OrdinalIgnoreCase)) continue;
                        step.Set(prop.Name, ConvertJsonValue(prop.Value));
                    }
                    rules.Steps.Add(step);
                }
                catch
                {
                    // Never let a malformed step abort parsing of the rest.
                }
            }
        }

        return rules;
    }

    public string ToJson()
    {
        var root = new JsonObject
        {
            ["applyTo"] = ApplyTo == ApplyTo.NameAndExtension ? "nameAndExtension" : "name",
            ["sort"] = Sort switch
            {
                SortMode.Created => "created",
                SortMode.Modified => "modified",
                _ => "name",
            },
        };

        var stepsArray = new JsonArray();
        foreach (var step in Steps)
        {
            var stepObj = new JsonObject { ["op"] = step.Op };
            foreach (var kv in step.Params)
            {
                stepObj[kv.Key] = kv.Value switch
                {
                    string s => JsonValue.Create(s),
                    long l => JsonValue.Create(l),
                    bool b => JsonValue.Create(b),
                    null => null,
                    _ => JsonValue.Create(kv.Value.ToString()),
                };
            }
            stepsArray.Add(stepObj);
        }
        root["steps"] = stepsArray;

        var options = new JsonSerializerOptions { WriteIndented = true };
        return root.ToJsonString(options);
    }

    private static bool TryGetPropertyCaseInsensitive(JsonElement obj, string name, out JsonElement value)
    {
        if (obj.ValueKind == JsonValueKind.Object)
        {
            foreach (var p in obj.EnumerateObject())
            {
                if (string.Equals(p.Name, name, StringComparison.OrdinalIgnoreCase))
                {
                    value = p.Value;
                    return true;
                }
            }
        }
        value = default;
        return false;
    }

    private static object? ConvertJsonValue(JsonElement el)
    {
        switch (el.ValueKind)
        {
            case JsonValueKind.String:
                return el.GetString();
            case JsonValueKind.Number:
                if (el.TryGetInt64(out var l)) return l;
                if (el.TryGetDouble(out var d)) return (long)d;
                return null;
            case JsonValueKind.True:
                return true;
            case JsonValueKind.False:
                return false;
            case JsonValueKind.Null:
                return null;
            default:
                // object/array parameter values: best-effort, keep raw text.
                return el.GetRawText();
        }
    }
}

