using BatchRenameStudio.Cli;

namespace BatchRenameStudio;

internal static class Program
{
    [STAThread]
    static int Main(string[] args)
    {
        var options = CliOptions.Parse(args);

        switch (options.Mode)
        {
            case CliMode.Gui:
                ApplicationConfiguration.Initialize();
                Application.Run(new Ui.MainForm());
                return 0;

            case CliMode.Help:
                ConsoleBridge.Attach();
                Console.WriteLine(CliOptions.UsageText);
                return 0;

            case CliMode.UsageError:
                ConsoleBridge.Attach();
                Console.Error.WriteLine($"error: {options.ErrorMessage}");
                Console.Error.WriteLine(CliOptions.UsageText);
                return 2;

            case CliMode.Headless:
                ConsoleBridge.Attach();
                return HeadlessRunner.Run(options);

            default:
                return 2;
        }
    }
}
using System.Runtime.InteropServices;
using System.Text;

namespace BatchRenameStudio.Cli;

/// <summary>
/// The app is built as WinExe, so it starts with no console attached. Before
/// any headless output, attach to the parent console (if any) and rebind
/// stdout/stderr so writes actually land — whether the process is run from an
/// interactive console, piped, or redirected to a file. Never allocates a new
/// console window.
/// </summary>
internal static class ConsoleBridge
{
    private const int ATTACH_PARENT_PROCESS = -1;

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool AttachConsole(int dwProcessId);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr GetStdHandle(int nStdHandle);

    private const int STD_OUTPUT_HANDLE = -11;
    private static readonly IntPtr InvalidHandleValue = new(-1);

    private static bool _attached;

    public static void Attach()
    {
        if (_attached) return;
        _attached = true;

        // If stdout is already a valid handle (redirected to a file or a pipe by
        // the caller), the process already has working standard handles and
        // attaching to the parent's console would clobber them. Only attach
        // when there is no console AND no redirection (plain interactive run
        // of a WinExe app), i.e. the handle is missing/invalid.
        var existingStdOut = GetStdHandle(STD_OUTPUT_HANDLE);
        if (existingStdOut == IntPtr.Zero || existingStdOut == InvalidHandleValue)
        {
            // Ignore the return value: it fails harmlessly when there is no
            // parent console to attach to.
            AttachConsole(ATTACH_PARENT_PROCESS);
        }

        var encoding = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false);

        var stdout = new StreamWriter(Console.OpenStandardOutput(), encoding) { AutoFlush = true };
        Console.SetOut(stdout);

        var stderr = new StreamWriter(Console.OpenStandardError(), encoding) { AutoFlush = true };
        Console.SetError(stderr);
    }
}
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// Executes a --plan / --explain run (SPEC §8). Never mutates the scanned
/// folder — the only filesystem write is the --out file.
/// </summary>
internal static class HeadlessRunner
{
    public static int Run(CliOptions options)
    {
        try
        {
            if (!Directory.Exists(options.Dir))
            {
                Console.Error.WriteLine($"error: directory not found: {options.Dir}");
                return 3;
            }

            if (!File.Exists(options.Rules))
            {
                Console.Error.WriteLine($"error: rules file not found: {options.Rules}");
                return 3;
            }

            string rulesText;
            try
            {
                rulesText = File.ReadAllText(options.Rules!);
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
            {
                Console.Error.WriteLine($"error: could not read rules file: {ex.Message}");
                return 3;
            }

            RuleSet rules;
            try
            {
                rules = RuleSet.FromJson(rulesText);
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"error: rules file is not valid JSON: {ex.Message}");
                return 3;
            }

            var result = RenameEngine.RunFolder(options.Dir!, rules);
            var plan = result.ToPlan();

            string json = options.IsPlan
                ? JsonIo.SerializePlan(plan)
                : JsonIo.SerializeTrace(result.ToTrace());

            string outPath = options.Out!;
            try
            {
                JsonIo.WriteUtf8NoBom(outPath, json);
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
            {
                Console.Error.WriteLine($"error: could not write output file: {ex.Message}");
                return 4;
            }

            var summary = plan.Summary;
            string line = options.IsPlan
                ? $"plan total={summary.Total} ok={summary.Ok} collision={summary.Collision} unchanged={summary.Unchanged} invalid={summary.Invalid} out={outPath}"
                : $"explain files={summary.Total} ok={summary.Ok} collision={summary.Collision} unchanged={summary.Unchanged} invalid={summary.Invalid} out={outPath}";

            Console.WriteLine(line);
            return 0;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return 4;
        }
    }
}

