using BatchRenameStudio.Core;

namespace BatchRenameStudio.Services;

public sealed record RenameOutcome(int Renamed, int Skipped, IReadOnlyList<string> Errors, string? JournalPath);

/// <summary>
/// Applies a computed rename plan to disk using a two-phase temp-rename algorithm,
/// so cyclic renames (a-&gt;b, b-&gt;a) succeed without an intermediate collision.
/// </summary>
public static class RenameExecutor
{
    public static RenameOutcome Apply(string folder, PlanResult plan)
    {
        var okItems = plan.Items.Where(i => i.Status == "ok").ToList();
        int skipped = plan.Items.Count - okItems.Count;

        if (okItems.Count == 0)
        {
            return new RenameOutcome(0, skipped, Array.Empty<string>(), null);
        }

        var errors = new List<string>();
        var pairs = okItems.Select(i => (From: i.Original, To: i.Proposed)).ToList();

        int renamed = TwoPhaseRename(folder, pairs, errors);

        string? journalPath = null;
        if (renamed > 0 && errors.Count == 0)
        {
            var entries = pairs.Select(p => new UndoEntry(p.From, p.To)).ToList();
            journalPath = UndoJournal.Write(folder, entries);
        }

        return new RenameOutcome(renamed, skipped + (pairs.Count - renamed), errors, journalPath);
    }

    /// <summary>
    /// Phase 1: rename every source to a unique "&lt;guid&gt;.brs-tmp" name in the same
    /// folder. Phase 2: rename every temp file to its final name. If phase 2 fails
    /// part-way, roll back everything still in temp form to its original name and
    /// report the error. No ".brs-tmp" files are left behind either way.
    /// Returns the count of pairs that ended up successfully renamed.
    /// </summary>
    internal static int TwoPhaseRename(string folder, IReadOnlyList<(string From, string To)> pairs, List<string> errors)
    {
        if (pairs.Count == 0) return 0;

        // Phase 1: source -> temp
        var tempNames = new Dictionary<int, string>(); // index -> temp file name, for successfully moved entries
        for (int i = 0; i < pairs.Count; i++)
        {
            var (from, _) = pairs[i];
            var sourcePath = Path.Combine(folder, from);
            var tempName = Guid.NewGuid().ToString("N") + ".brs-tmp";
            var tempPath = Path.Combine(folder, tempName);

            if (!File.Exists(sourcePath))
            {
                errors.Add($"missing source: {from}");
                continue;
            }

            try
            {
                File.Move(sourcePath, tempPath);
                tempNames[i] = tempName;
            }
            catch (Exception ex)
            {
                errors.Add($"phase1 failed for '{from}': {ex.Message}");
            }
        }

        // Phase 2: temp -> final
        int completed = 0;
        var phase2Failed = false;
        foreach (var kv in tempNames.ToList())
        {
            int i = kv.Key;
            var tempPath = Path.Combine(folder, kv.Value);
            var finalPath = Path.Combine(folder, pairs[i].To);

            try
            {
                File.Move(tempPath, finalPath);
                tempNames.Remove(i);
                completed++;
            }
            catch (Exception ex)
            {
                errors.Add($"phase2 failed for '{pairs[i].To}': {ex.Message}");
                phase2Failed = true;
            }
        }

        // Roll back anything still stuck in temp form.
        if (phase2Failed && tempNames.Count > 0)
        {
            foreach (var kv in tempNames)
            {
                int i = kv.Key;
                var tempPath = Path.Combine(folder, kv.Value);
                var originalPath = Path.Combine(folder, pairs[i].From);
                try
                {
                    File.Move(tempPath, originalPath);
                }
                catch (Exception ex)
                {
                    errors.Add($"rollback failed for '{pairs[i].From}' (left as '{kv.Value}'): {ex.Message}");
                }
            }
        }

        return completed;
    }
}

