using System.Text.Json;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Services;

public sealed record UndoEntry(string From, string To);

public sealed class UndoJournalData
{
    public string Folder { get; set; } = "";
    public string TimestampUtc { get; set; } = "";
    public List<UndoEntry> Entries { get; set; } = new();
}

/// <summary>
/// Persists and replays undo journals for applied renames.
/// Directory: %LOCALAPPDATA%\BatchRenameStudioPro\undo\
/// File name: yyyyMMddTHHmmssfffZ.json
/// </summary>
public static class UndoJournal
{
    public static string Directory
    {
        get
        {
            var root = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
            return Path.Combine(root, "BatchRenameStudioPro", "undo");
        }
    }

    public static string Write(string folder, IReadOnlyList<UndoEntry> entries)
    {
        if (!System.IO.Directory.Exists(Directory))
        {
            System.IO.Directory.CreateDirectory(Directory);
        }

        var now = DateTime.UtcNow;
        var fileName = now.ToString("yyyyMMddTHHmmssfffZ") + ".json";
        var path = Path.Combine(Directory, fileName);

        var data = new UndoJournalData
        {
            Folder = folder,
            TimestampUtc = now.ToString("yyyy-MM-ddTHH:mm:ss.fffZ"),
            Entries = entries.ToList(),
        };

        var json = Serialize(data);
        JsonIo.WriteUtf8NoBom(path, json);
        return path;
    }

    /// <summary>
    /// Newest journal file (by filename, which sorts chronologically) whose
    /// "folder" matches (case-insensitively) and has not yet been consumed
    /// (i.e. does not end in ".undone").
    /// </summary>
    public static string? FindLatest(string folder)
    {
        if (!System.IO.Directory.Exists(Directory)) return null;

        var candidates = System.IO.Directory.GetFiles(Directory, "*.json")
            .OrderByDescending(f => Path.GetFileName(f), StringComparer.Ordinal)
            .ToList();

        foreach (var path in candidates)
        {
            UndoJournalData? data;
            try
            {
                data = Deserialize(File.ReadAllText(path));
            }
            catch
            {
                continue;
            }

            if (data is null) continue;

            if (string.Equals(data.Folder, folder, StringComparison.OrdinalIgnoreCase))
            {
                return path;
            }
        }

        return null;
    }

    /// <summary>
    /// Replays the journal in reverse using the same two-phase rename algorithm,
    /// then marks it consumed by renaming to "*.json.undone". Missing/occupied
    /// targets are skipped and reported; the rest still proceeds.
    /// </summary>
    public static UndoOutcome Undo(string journalPath)
    {
        var data = Deserialize(File.ReadAllText(journalPath));
        if (data is null)
        {
            return new UndoOutcome(0, new List<string> { "Journal is unreadable or malformed." });
        }

        var folder = data.Folder;
        var errors = new List<string>();

        // Reverse the entries: to -> from.
        var reversed = new List<UndoEntry>(data.Entries.Count);
        for (int i = data.Entries.Count - 1; i >= 0; i--)
        {
            var e = data.Entries[i];
            reversed.Add(new UndoEntry(e.To, e.From));
        }

        // Filter out entries whose source (the "to" from the original apply) is missing,
        // or whose target ("from") already exists (and isn't itself part of this undo set).
        var usable = new List<UndoEntry>();
        var targetSet = new HashSet<string>(reversed.Select(e => e.To), StringComparer.OrdinalIgnoreCase);
        foreach (var e in reversed)
        {
            var fromPath = Path.Combine(folder, e.From);
            if (!File.Exists(fromPath))
            {
                errors.Add($"missing: {e.From}");
                continue;
            }

            var toPath = Path.Combine(folder, e.To);
            if (File.Exists(toPath) && !targetSet.Contains(Path.GetFileName(toPath)))
            {
                // Target occupied by something that is not part of this undo's own moves.
                errors.Add($"occupied: {e.To}");
                continue;
            }

            usable.Add(e);
        }

        int renamed = RenameExecutor.TwoPhaseRename(folder, usable.Select(e => (e.From, e.To)).ToList(), errors);

        var donePath = journalPath + ".undone";
        try
        {
            File.Move(journalPath, donePath, overwrite: true);
        }
        catch (Exception ex)
        {
            errors.Add($"could not mark journal consumed: {ex.Message}");
        }

        return new UndoOutcome(renamed, errors);
    }

    private static string Serialize(UndoJournalData data)
    {
        using var stream = new MemoryStream();
        using (var writer = new Utf8JsonWriter(stream, new JsonWriterOptions { Indented = true }))
        {
            writer.WriteStartObject();
            writer.WriteString("folder", data.Folder);
            writer.WriteString("timestampUtc", data.TimestampUtc);
            writer.WriteStartArray("entries");
            foreach (var e in data.Entries)
            {
                writer.WriteStartObject();
                writer.WriteString("from", e.From);
                writer.WriteString("to", e.To);
                writer.WriteEndObject();
            }
            writer.WriteEndArray();
            writer.WriteEndObject();
        }
        return System.Text.Encoding.UTF8.GetString(stream.ToArray());
    }

    private static UndoJournalData? Deserialize(string json)
    {
        using var doc = JsonDocument.Parse(json, new JsonDocumentOptions
        {
            AllowTrailingCommas = true,
            CommentHandling = JsonCommentHandling.Skip,
        });
        var root = doc.RootElement;
        if (root.ValueKind != JsonValueKind.Object) return null;

        var data = new UndoJournalData();
        if (root.TryGetProperty("folder", out var f) && f.ValueKind == JsonValueKind.String)
        {
            data.Folder = f.GetString() ?? "";
        }
        if (root.TryGetProperty("timestampUtc", out var t) && t.ValueKind == JsonValueKind.String)
        {
            data.TimestampUtc = t.GetString() ?? "";
        }
        if (root.TryGetProperty("entries", out var entries) && entries.ValueKind == JsonValueKind.Array)
        {
            foreach (var el in entries.EnumerateArray())
            {
                if (el.ValueKind != JsonValueKind.Object) continue;
                string from = el.TryGetProperty("from", out var fr) && fr.ValueKind == JsonValueKind.String ? fr.GetString() ?? "" : "";
                string to = el.TryGetProperty("to", out var tp) && tp.ValueKind == JsonValueKind.String ? tp.GetString() ?? "" : "";
                data.Entries.Add(new UndoEntry(from, to));
            }
        }
        return data;
    }
}

public sealed record UndoOutcome(int Restored, IReadOnlyList<string> Errors);

